\title{The Degree-One Triviality Threshold for Grassmann Schemes:\\
A Verified Combinatorial Backbone}
\author{Aristotle}
\date{2026-06-28}

\begin{document}
\maketitle

\begin{abstract}
The Grassmann scheme $J_q(n,k)$ is the association scheme whose points are the
$k$-dimensional subspaces of an $n$-dimensional vector space over the finite field
$\Fq$. A central rigidity question is the \emph{degree-one triviality threshold
conjecture}: for every prime power $q$ and integers $2 \le k \le n/2$, if
$n \ge 2k+1$ then every Boolean degree-one function on $J_q(n,k)$ is \emph{trivial},
i.e.\ a $\{0,1\}$-linear combination of point indicators and their duals. The
conjecture is known for $q=2$ (all $k$) and for $q \in \{3,4,5\}$ with $k=2$. We
develop and formally verify the combinatorial backbone required to state the
conjecture faithfully and to expose its structural levers. We define the Gaussian
binomial coefficient $\binom{n}{k}_q$ through the division-free $q$-Pascal
recurrence and establish: the classical degeneration $\binom{n}{k}_1 =
\binom{n}{k}$; nonemptiness $\binom{n}{k}_q \ge 1$; the point count
$\binom{n}{1}_q = 1 + q + \cdots + q^{n-1}$; the mirror symmetry
$\binom{n}{k}_q = \binom{n}{n-k}_q$, whose $k=1$ slice is point--hyperplane
duality; and strict ambient monotonicity $\binom{n}{k}_q < \binom{n+1}{k}_q$ for
$q \ge 2$. In the classical limit we transport unimodality, ambient monotonicity,
and total mass $\sum_{k=0}^n \binom{n}{k}_1 = 2^n$. We explain how the mirror
symmetry makes the trivial family duality-closed (a sharpness prediction at $n=2k$)
and how strict growth conjecturally upgrades to a $q$-uniform spectral gap.
\end{abstract}

\section{Introduction}

\subsection{Association schemes of subsets and subspaces}
The \emph{Johnson scheme} $J(n,k)$ has as its points the $k$-element subsets of
$\{1,\dots,n\}$, related by intersection size. Its linear-algebraic $q$-analogue is
the \emph{Grassmann scheme} $J_q(n,k)$, whose points are the $k$-dimensional
subspaces of $\Fq^n$, related by intersection dimension. These are prototypical
distance-regular, Q-polynomial association schemes, and their harmonic analysis
underlies extremal combinatorics, coding theory, and the analysis of Boolean
functions. The number of points of $J_q(n,k)$ is the \emph{Gaussian binomial
coefficient} $\binom{n}{k}_q$, the canonical $q$-analogue of $\binom{n}{k}$.

\subsection{Boolean degree-one functions and triviality}
Each association scheme carries a canonical orthogonal eigenspace decomposition of
the function space on its points. The \emph{degree-one} functions occupy the
trivial together with the first nontrivial eigenspace --- the linear layer of the
scheme's Fourier analysis. A function is \emph{Boolean} if it is $\{0,1\}$-valued.
On $J_q(n,k)$ there are two canonical families: \emph{point indicators}
$\mathbf{1}_{p\subseteq\cdot}$ for a fixed line $p$, and \emph{dual indicators}
$\mathbf{1}_{\cdot\subseteq H}$ for a fixed hyperplane $H$. A Boolean degree-one
function is \emph{trivial} if it is a $\{0,1\}$-combination of these.

\subsection{The threshold conjecture}
\begin{conjecture}[Degree-one triviality threshold]\label{conj:main}
For every prime power $q$ and integers $k,n$ with $2 \le k \le n/2$, if
$n \ge 2k+1$ then every Boolean degree-one function on $J_q(n,k)$ is trivial.
\end{conjecture}
The case $q=2$ is known for all $k$; the cases $q\in\{3,4,5\}$ are known for $k=2$.
Conjecture~\ref{conj:main} asserts uniformity across all prime powers once
$n \ge 2k+1$.

\subsection{Contributions}
We formalize and verify the counting layer underpinning any faithful attack on
Conjecture~\ref{conj:main}: a division-free construction of $\binom{n}{k}_q$ with
the identities \texttt{qBinom\_one}, \texttt{qBinom\_pos},
\texttt{qBinom\_one\_eq\_geom}, \texttt{qBinom\_symm},
\texttt{point\_hyperplane\_duality}, \texttt{qBinom\_strictMono\_left}
(Section~\ref{sec:backbone}); the exact $q\to1$ degeneration with transported facts
\texttt{qBinom\_one\_unimodal\_bound}, \texttt{qBinom\_one\_mono\_ambient},
\texttt{qBinom\_one\_total\_mass} (Section~\ref{sec:limit}); and a structural reading
of the threshold (Section~\ref{sec:structure}). Every numbered theorem corresponds
to a machine-checked statement.

\section{Definitions}

\begin{definition}[Gaussian binomial via $q$-Pascal]\label{def:qbinom}
The Gaussian binomial coefficient $\binom{n}{k}_q$ (\texttt{qBinom q n k}) is
defined by
\[
\binom{n}{0}_q = 1, \qquad \binom{0}{k+1}_q = 0,
\]
\[
\binom{n+1}{k+1}_q = \binom{n}{k}_q + q^{\,k+1}\binom{n}{k+1}_q.
\]
\end{definition}
This first $q$-Pascal recurrence defines $\binom{n}{k}_q$ as a natural number with
no division; at $q=1$ it is ordinary Pascal addition.

\begin{definition}[Grassmann point set]
For a prime power $q$, the points of $J_q(n,k)$ are the $k$-dimensional subspaces of
$\Fq^n$; their number is $\binom{n}{k}_q$. The points of $J_q(n,1)$ are the lines;
the hyperplanes are the points of $J_q(n,n-1)$.
\end{definition}

\begin{definition}[Trivial Boolean degree-one function]
A Boolean degree-one function $f$ on $J_q(n,k)$ is \emph{trivial} if
\[
f = \sum_p a_p\,\mathbf{1}_{p\subseteq\cdot} + \sum_H b_H\,\mathbf{1}_{\cdot\subseteq H},
\qquad a_p, b_H \in \{0,1\},
\]
where $p$ ranges over lines and $H$ over hyperplanes.
\end{definition}

\section{The Gaussian-binomial backbone}\label{sec:backbone}

All identities are proved by induction on the recurrence of
Definition~\ref{def:qbinom}; none reduces to a trivial computation.

\begin{theorem}[\texttt{qBinom\_one}: classical degeneration]\label{thm:one}
For all $n,k$, $\ \binom{n}{k}_1 = \binom{n}{k}.$
\end{theorem}
\begin{proof}[Proof sketch]
At $q=1$ the recurrence becomes $\binom{n+1}{k+1}_1 = \binom{n}{k}_1 +
\binom{n}{k+1}_1$, ordinary Pascal addition with identical base cases; induct on
$n$ with $k$ universally quantified.
\end{proof}
Thus $|J_1(n,k)| = \binom{n}{k} = |J(n,k)|$: the $q\to1$ limit is the Johnson scheme.

\begin{theorem}[\texttt{qBinom\_pos}: nonemptiness]\label{thm:pos}
If $q \ge 1$ and $k \le n$ then $\binom{n}{k}_q \ge 1$.
\end{theorem}
\begin{proof}[Proof sketch]
Induct on $n$. Base: $\binom{n}{0}_q = 1$. Step: $\binom{n+1}{k+1}_q =
\binom{n}{k}_q + q^{k+1}\binom{n}{k+1}_q \ge \binom{n}{k}_q \ge 1$. The hypothesis
$q \ge 1$ is load-bearing; at $q=0$ positivity can fail above the diagonal.
\end{proof}

\begin{theorem}[\texttt{qBinom\_one\_eq\_geom}: point count]\label{thm:geom}
For $n \ge 1$, $\ \binom{n}{1}_q = \sum_{i=0}^{n-1} q^i = 1 + q + \cdots + q^{n-1}.$
\end{theorem}
\begin{proof}[Proof sketch]
Induct on $n$ via the $k=0$ recurrence: $\binom{n+1}{1}_q = 1 + q\binom{n}{1}_q$.
Geometrically $\binom{n}{1}_q = \frac{q^n-1}{q-1}$ counts the lines of $\Fq^n$.
\end{proof}

\begin{theorem}[Second $q$-Pascal recurrence]\label{thm:pascal2}
For all $n,k$, $\ \binom{n+1}{k+1}_q = q^{\,n-k}\binom{n}{k}_q + \binom{n}{k+1}_q.$
\end{theorem}
\begin{proof}[Proof sketch]
The $q^{n-k}$-twisted partner of Definition~\ref{def:qbinom}, proved by a parallel
induction; it is the auxiliary identity that drives the symmetry induction.
\end{proof}

\begin{theorem}[\texttt{qBinom\_symm}: mirror symmetry]\label{thm:symm}
For $k \le n$, $\ \binom{n}{k}_q = \binom{n}{\,n-k\,}_q.$
\end{theorem}
\begin{proof}[Proof sketch]
Strong induction on $n$ using both Pascal recurrences
(Defs.~\ref{def:qbinom},~\ref{thm:pascal2}): each expresses the two sides in terms
of strictly smaller symmetric pairs matched by the inductive hypothesis.
Geometrically this is the bijection $V \mapsto V^\perp$. This is the load-bearing
identity of the theory.
\end{proof}

\begin{theorem}[\texttt{point\_hyperplane\_duality}]\label{thm:dual}
For $n \ge 1$, $\ \binom{n}{1}_q = \binom{n}{\,n-1\,}_q$: the number of points
equals the number of hyperplanes.
\end{theorem}
\begin{proof}[Proof sketch]
The $k=1$ instance of Theorem~\ref{thm:symm}; the counting shadow of point/dual
duality, under which point and dual indicators are exchanged by $V\mapsto V^\perp$.
\end{proof}

\begin{theorem}[\texttt{qBinom\_strictMono\_left}: strict ambient growth]\label{thm:mono}
If $q \ge 2$ and $1 \le k \le n$ then $\binom{n}{k}_q < \binom{n+1}{k}_q$.
\end{theorem}
\begin{proof}[Proof sketch]
The difference is a sum of strictly positive terms involving $q^{k} \ge 2^k$ and a
positive lower-order $q$-binomial (Theorem~\ref{thm:pos}). The hypothesis $q\ge2$ is
essential: at $q=1$ this is strict monotonicity of ordinary binomials in $n$, which
plateaus past the central column.
\end{proof}

\section{The classical $q \to 1$ limit}\label{sec:limit}

Via Theorem~\ref{thm:one}, three classical facts transport. We use middle-coefficient
maximality $\binom{n}{k}\le\binom{n}{\lfloor n/2\rfloor}$, monotonicity
$\binom{n}{k}\le\binom{m}{k}$ for $n\le m$, and $\sum_{k=0}^n\binom{n}{k}=2^n$.

\begin{theorem}[\texttt{qBinom\_one\_unimodal\_bound}]\label{thm:uni}
For all $n,k$, $\ \binom{n}{k}_1 \le \binom{n}{\lfloor n/2\rfloor}_1.$
\end{theorem}
\begin{proof}[Proof sketch]
Rewrite both sides by Theorem~\ref{thm:one} and apply middle-coefficient maximality.
\end{proof}
This links the threshold $n\ge 2k+1$ to unimodality: that regime keeps $k$ strictly
below the central index, where the scheme is still growing.

\begin{theorem}[\texttt{qBinom\_one\_mono\_ambient}]\label{thm:monolim}
If $n \le m$ then $\binom{n}{k}_1 \le \binom{m}{k}_1$.
\end{theorem}
\begin{proof}[Proof sketch]
Rewrite via Theorem~\ref{thm:one} and apply monotonicity of $\binom{\cdot}{k}$; the
$q=1$ shadow of Theorem~\ref{thm:mono}.
\end{proof}

\begin{theorem}[\texttt{qBinom\_one\_total\_mass}]\label{thm:mass}
For all $n$, $\ \sum_{k=0}^{n}\binom{n}{k}_1 = 2^n.$
\end{theorem}
\begin{proof}[Proof sketch]
Rewrite the summand pointwise via Theorem~\ref{thm:one}, then apply the row-sum
identity. The classical limit of the Grassmann poset is the Boolean lattice on $n$
elements.
\end{proof}

\section{Structural consequences for the threshold}\label{sec:structure}

\subsection{The trivial family is duality-closed}
By Theorem~\ref{thm:symm}, $V\mapsto V^\perp$ is a bijection
$J_q(n,k)\leftrightarrow J_q(n,n-k)$ exchanging point and dual indicators. Hence the
trivial family is closed under scheme duality: the duality-closed $\{0,1\}$-span of
rank-one indicators. Conjecture~\ref{conj:main} states that above the threshold the
degree-one Boolean functions coincide with this span.

\subsection{Sharpness at $n=2k$}
\begin{conjecture}[Sharpness]\label{conj:sharp}
For every prime power $q$ and $k \ge 2$, the scheme $J_q(2k,k)$ (failing
$n\ge2k+1$) admits a non-trivial Boolean degree-one function.
\end{conjecture}
At $n=2k$, Theorem~\ref{thm:symm} gives $\binom{2k}{k}_q = \binom{2k}{\,2k-k\,}_q$
with $k=n-k$: the scheme is self-dual. Self-duality is conjectured to furnish an
additional $\pm1$ eigenvector beyond the point/dual span --- precisely a non-trivial
degree-one Boolean function. The symmetry theorem identifies the self-dual locus
exactly at $n=2k$.

\subsection{Strict growth and a uniform spectral gap}
\begin{conjecture}[Spectral gap]\label{conj:gap}
For $q \ge 2$ and $1 \le k \le n$, the inequality of Theorem~\ref{thm:mono}
upgrades to a quantitative gap: the second-largest eigenvalue of the $J_q(n,k)$
adjacency operator is bounded away from the largest by a factor depending only on
$q$, uniformly in $n$.
\end{conjecture}
Strict monotonicity in the ambient dimension is the counting shadow of a
non-degenerate scheme refinement, equivalent to a uniform spectral gap. Since strict
growth holds for $q\ge2$ and fails at $q\le1$, the gap can depend only on $q$.

\section{Algorithms}

\textbf{Algorithm (bottom-up $q$-Pascal).} Compute $\binom{n}{k}_q$ by filling the
triangle of Definition~\ref{def:qbinom}; $O(nk)$ big-integer additions, $O(k)$ space.

\textbf{Algorithm (point count).} $\binom{n}{1}_q = \sum_{i=0}^{n-1}q^i$
(Theorem~\ref{thm:geom}); $O(n)$.

\textbf{Algorithm (symmetry check).} Compare $\binom{n}{k}_q$ with
$\binom{n}{n-k}_q$ over a parameter window (Theorem~\ref{thm:symm}).

\textbf{Algorithm (classical-limit check).} Compare the $q=1$ row against
$\binom{n}{k}$ and against $2^n$ (Theorems~\ref{thm:one},~\ref{thm:mass}).

\section{Applications}
The points of $J_q(n,k)$ are codewords of constant-dimension subspace codes used in
random linear network coding; exact counts and Theorem~\ref{thm:symm} control code
sizes and duals. Degree-one triviality is the linear-algebraic stability statement
behind $q$-analogues of Erd\H{o}s--Ko--Rado, and the ``low-degree Boolean functions
are juntas'' principle transplanted to Grassmann domains.

\section{Discussion and future work}
The verified backbone makes Conjecture~\ref{conj:main} a precise, structurally
anchored target: the mirror symmetry makes the trivial family duality-closed and
pins the self-dual locus at $n=2k$ (sharpness), while strict ambient growth for
$q\ge2$ is the counting shadow of a conjectural $q$-uniform spectral gap. The
decisive open ingredient is a $q$-uniform eigenvalue/interlacing bound on the
Grassmann adjacency operator, now expressible against the single inductive object
$\binom{n}{k}_q$. Verifying Conjecture~\ref{conj:sharp} for small $(q,k)$ would
confirm sharpness and constrain the extremal eigenvector.

